    final Integer toClientID = ClientHelper.createClient(this.requestSpec, this.responseSpec, "01 January 2011", String.valueOf(toOfficeId));
    Assertions.assertNotNull(toClientID);
    final Integer toSavingsProductID = createSavingsProduct(this.requestSpec, this.responseSpec, MINIMUM_OPENING_BALANCE, assetAccount, incomeAccount, expenseAccount, liabilityAccount);
    Assertions.assertNotNull(toSavingsProductID);
    final Integer toSavingsID = this.savingsAccountHelper.applyForSavingsApplication(toClientID, toSavingsProductID, ACCOUNT_TYPE_INDIVIDUAL);
