    // Verifying toSavings Account Balance after Account Transfer
    assertEquals(toSavingsBalance, toSavingsSummaryAfter.get("accountBalance"), "Verifying From Savings Account Balance after Account Transfer");
    final JournalEntry[] office1LiabilityEntries = { new JournalEntry(Float.parseFloat(ACCOUNT_TRANSFER_AMOUNT_ADJUST), JournalEntry.TransactionType.CREDIT) };
    final JournalEntry[] office2LiabilityEntries = { new JournalEntry(Float.parseFloat(ACCOUNT_TRANSFER_AMOUNT_ADJUST), JournalEntry.TransactionType.DEBIT) };
    this.journalEntryHelper.checkJournalEntryForLiabilityAccount(fromOfficeId, liabilityTransferAccount, AccountTransferHelper.ACCOUNT_TRANSFER_DATE, office1LiabilityEntries);
    this.journalEntryHelper.checkJournalEntryForLiabilityAccount(toOfficeId, liabilityTransferAccount, AccountTransferHelper.ACCOUNT_TRANSFER_DATE, office2LiabilityEntries);
