    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 September 2011", assetAccountInitialEntry);
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 September 2011", new JournalEntry(Float.parseFloat("100.00"), JournalEntry.TransactionType.CREDIT));
    loanCharges.clear();
    loanCharges = this.loanTransactionHelper.getLoanCharges(loanID);
    validateCharge(flatDisbursement, loanCharges, "100", "0.00", "100.0", "0.0");
    LOG.info("-------------Make repayment 1-----------");
    this.loanTransactionHelper.makeRepayment("20 October 2011", Float.parseFloat("3301.49"), loanID);
    loanCharges.clear();
    loanCharges = this.loanTransactionHelper.getLoanCharges(loanID);
    validateCharge(flatDisbursement, loanCharges, "100", "0.00", "100.0", "0.0");
    validateCharge(flatSpecifiedDueDate, loanCharges, "100", "0.00", "100.0", "0.0");
    validateCharge(flatInstallmentFee, loanCharges, "50", "150.00", "50.0", "0.0");
    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 October 2011", new JournalEntry(Float.parseFloat("3301.49"), JournalEntry.TransactionType.DEBIT), new JournalEntry(Float.parseFloat("2911.49"), JournalEntry.TransactionType.CREDIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 October 2011", new JournalEntry(Float.parseFloat("150.00"), JournalEntry.TransactionType.CREDIT), new JournalEntry(Float.parseFloat("240.00"), JournalEntry.TransactionType.CREDIT));
    this.loanTransactionHelper.addChargesForLoan(loanID, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(flatSpecifiedDueDate), "29 October 2011", "100"));
    loanSchedule.clear();
    loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(this.requestSpec, this.responseSpec, loanID);
    secondInstallment = loanSchedule.get(2);
    validateNumberForEqual("150.00", String.valueOf(secondInstallment.get("feeChargesDue")));
    this.loanTransactionHelper.waiveChargesForLoan(loanID, (Integer) getloanCharge(flatInstallmentFee, loanCharges).get("id"), LoanTransactionHelper.getWaiveChargeJSON(String.valueOf(2)));
    loanCharges.clear();
    loanCharges = this.loanTransactionHelper.getLoanCharges(loanID);
    validateCharge(flatInstallmentFee, loanCharges, "50", "100.00", "50.0", "50.0");
    LOG.info("----------Make repayment 2------------");
    this.loanTransactionHelper.makeRepayment("20 November 2011", Float.parseFloat("3251.49"), loanID);
    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 November 2011", new JournalEntry(Float.parseFloat("3251.49"), JournalEntry.TransactionType.DEBIT), new JournalEntry(Float.parseFloat("2969.72"), JournalEntry.TransactionType.CREDIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 November 2011", new JournalEntry(Float.parseFloat("100.00"), JournalEntry.TransactionType.CREDIT), new JournalEntry(Float.parseFloat("181.77"), JournalEntry.TransactionType.CREDIT));
    loanSchedule.clear();
    loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(this.requestSpec, this.responseSpec, loanID);
    secondInstallment = loanSchedule.get(2);
    validateNumberForEqual("0", String.valueOf(secondInstallment.get("totalOutstandingForPeriod")));
    LOG.info("--------------Waive interest---------------");
    this.loanTransactionHelper.waiveInterest("20 December 2011", String.valueOf(61.79), loanID);
    loanSchedule.clear();
    loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(this.requestSpec, this.responseSpec, loanID);
    HashMap thirdInstallment = loanSchedule.get(3);
    validateNumberForEqual("60.59", String.valueOf(thirdInstallment.get("interestOutstanding")));
