    this.loanTransactionHelper.addChargesForLoan(loanID, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(flatPenaltySpecifiedDueDate), "29 September 2011", "100"));
    loanCharges.clear();
    loanCharges = this.loanTransactionHelper.getLoanCharges(loanID);
