    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 October 2011", new JournalEntry(Float.parseFloat("3301.49"), JournalEntry.TransactionType.DEBIT), new JournalEntry(Float.parseFloat("2811.49"), JournalEntry.TransactionType.CREDIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 October 2011", new JournalEntry(Float.parseFloat("100.00"), JournalEntry.TransactionType.CREDIT), new JournalEntry(Float.parseFloat("150.00"), JournalEntry.TransactionType.CREDIT), new JournalEntry(Float.parseFloat("240"), JournalEntry.TransactionType.CREDIT));
    LOG.info("----------Make repayment 3 advance------------");
    this.loanTransactionHelper.makeRepayment("20 November 2011", Float.parseFloat("3301.49"), loanID);
    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 November 2011", new JournalEntry(Float.parseFloat("3301.49"), JournalEntry.TransactionType.DEBIT), new JournalEntry(Float.parseFloat("3129.11"), JournalEntry.TransactionType.CREDIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 November 2011", new JournalEntry(Float.parseFloat("50.00"), JournalEntry.TransactionType.CREDIT), new JournalEntry(Float.parseFloat("122.38"), JournalEntry.TransactionType.CREDIT));
    this.loanTransactionHelper.addChargesForLoan(loanID, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(flatPenaltySpecifiedDueDate), "10 January 2012", "100"));
    loanSchedule.clear();
    loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(this.requestSpec, this.responseSpec, loanID);
    HashMap fourthInstallment = loanSchedule.get(4);
    validateNumberForEqual("100", String.valueOf(fourthInstallment.get("penaltyChargesOutstanding")));
    validateNumberForEqual("3239.68", String.valueOf(fourthInstallment.get("totalOutstandingForPeriod")));
