    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 January 2012", new JournalEntry(Float.parseFloat("100"), JournalEntry.TransactionType.DEBIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 January 2012", new JournalEntry(Float.parseFloat("100.00"), JournalEntry.TransactionType.CREDIT));
    loanSchedule.clear();
    loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(this.requestSpec, this.responseSpec, loanID);
    fourthInstallment = loanSchedule.get(4);
    validateNumberForEqual("0", String.valueOf(fourthInstallment.get("penaltyChargesOutstanding")));
    validateNumberForEqual("3139.68", String.valueOf(fourthInstallment.get("totalOutstandingForPeriod")));
    LOG.info("----------Make repayment 4 ------------");
    this.loanTransactionHelper.makeRepayment("20 January 2012", Float.parseFloat("3139.68"), loanID);
    this.journalEntryHelper.checkJournalEntryForAssetAccount(assetAccount, "20 January 2012", new JournalEntry(Float.parseFloat("3139.68"), JournalEntry.TransactionType.DEBIT), new JournalEntry(Float.parseFloat("3089.68"), JournalEntry.TransactionType.CREDIT));
    this.journalEntryHelper.checkJournalEntryForIncomeAccount(incomeAccount, "20 January 2012", new JournalEntry(Float.parseFloat("50.00"), JournalEntry.TransactionType.CREDIT));
}

