    addCharges(charges, flatAmountChargeOne, "50", "01 October 2011");
    Integer flatAmountChargeTwo = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "100", true));
    addCharges(charges, flatAmountChargeTwo, "100", "15 December 2011");
