            final HashMap updateSuccess1 = (HashMap) GlobalConfigurationHelper.updatePasswordResetDaysForGlobalConfiguration(this.requestSpec, this.responseSpec, configId, newValue, "false", "changes");
            Assertions.assertNotNull(updateSuccess1);
            /*
                 * Update without sending value and Enable as true - failure case
                 */
            ArrayList failure = (ArrayList) GlobalConfigurationHelper.updatePasswordResetDaysForGlobalConfiguration(this.requestSpec, this.httpStatusForidden, configId, null, newBooleanValue, CommonConstants.RESPONSE_ERROR);
            HashMap failureHash = (HashMap) failure.get(0);
            Assertions.assertEquals("error.msg.password.reset.days.value.must.be.greater.than.zero", failureHash.get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE), "Force Password Reset days value must be greater than zero.");
            break;
        }
    }
    /* Update other global configuration property */
    String otherConfigName = "maker-checker";
    for (Integer configIndex = 0; configIndex < globalConfig.size() - 1; configIndex++) {
        if (globalConfig.get(configIndex).get("name").equals(otherConfigName)) {
            String configId = globalConfig.get(configIndex).get("id").toString();
            Integer updateConfigId = GlobalConfigurationHelper.updateValueForGlobalConfiguration(this.requestSpec, this.responseSpec, configId, newValue);
            Assertions.assertNotNull(updateConfigId);
            break;
        }
    }
}

