@SuppressWarnings("unchecked")
@Test
public void testSavingsAccountTransactions() {
    this.savingsAccountHelper = new SavingsAccountHelper(this.requestSpec, this.responseSpec);
    SavingsAccountHelper savingsAccountHelperValidationError = new SavingsAccountHelper(this.requestSpec, new ResponseSpecBuilder().build());
    final Integer clientID = ClientHelper.createClient(this.requestSpec, this.responseSpec);
    Assertions.assertNotNull(clientID);
    Integer groupID = GroupHelper.createGroup(this.requestSpec, this.responseSpec, true);
    Assertions.assertNotNull(groupID);
    groupID = GroupHelper.associateClient(this.requestSpec, this.responseSpec, groupID.toString(), clientID.toString());
    Assertions.assertNotNull(groupID);
    final String minBalanceForInterestCalculation = null;
    final String minRequiredBalance = null;
    final String enforceMinRequiredBalance = "false";
    final Integer savingsProductID = createSavingsProduct(this.requestSpec, this.responseSpec, MINIMUM_OPENING_BALANCE, minBalanceForInterestCalculation, minRequiredBalance, enforceMinRequiredBalance);
    Assertions.assertNotNull(savingsProductID);
    final Integer savingsId = this.savingsAccountHelper.applyForSavingsApplication(groupID, savingsProductID, ACCOUNT_TYPE_GROUP);
    Assertions.assertNotNull(savingsId);
    HashMap savingsStatusHashMap = SavingsStatusChecker.getStatusOfSavings(this.requestSpec, this.responseSpec, savingsId);
    SavingsStatusChecker.verifySavingsIsPending(savingsStatusHashMap);
    savingsStatusHashMap = this.savingsAccountHelper.approveSavings(savingsId);
    SavingsStatusChecker.verifySavingsIsApproved(savingsStatusHashMap);
    List<HashMap> error = (List) savingsAccountHelperValidationError.withdrawalFromSavingsAccount(savingsId, "100", SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.account.is.not.active", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    error = (List) savingsAccountHelperValidationError.depositToSavingsAccount(savingsId, "100", SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.account.is.not.active", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    savingsStatusHashMap = this.savingsAccountHelper.activateSavings(savingsId);
    SavingsStatusChecker.verifySavingsIsActive(savingsStatusHashMap);
    HashMap summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    Float balance = Float.valueOf(MINIMUM_OPENING_BALANCE);
    assertEquals(balance, summary.get("accountBalance"), "Verifying opening Balance");
    Integer depositTransactionId = (Integer) this.savingsAccountHelper.depositToSavingsAccount(savingsId, DEPOSIT_AMOUNT, SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    HashMap depositTransaction = this.savingsAccountHelper.getSavingsTransaction(savingsId, depositTransactionId);
    balance += Float.parseFloat(DEPOSIT_AMOUNT);
    assertEquals(Float.valueOf(DEPOSIT_AMOUNT), depositTransaction.get("amount"), "Verifying Deposit Amount");
    assertEquals(balance, depositTransaction.get("runningBalance"), "Verifying Balance after Deposit");
    Integer withdrawTransactionId = (Integer) this.savingsAccountHelper.withdrawalFromSavingsAccount(savingsId, WITHDRAW_AMOUNT, SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    HashMap withdrawTransaction = this.savingsAccountHelper.getSavingsTransaction(savingsId, withdrawTransactionId);
    balance -= Float.parseFloat(WITHDRAW_AMOUNT);
    assertEquals(Float.valueOf(WITHDRAW_AMOUNT), withdrawTransaction.get("amount"), "Verifying Withdrawal Amount");
    assertEquals(balance, withdrawTransaction.get("runningBalance"), "Verifying Balance after Withdrawal");
    Integer newWithdrawTransactionId = this.savingsAccountHelper.updateSavingsAccountTransaction(savingsId, withdrawTransactionId, WITHDRAW_AMOUNT_ADJUSTED);
    HashMap newWithdrawTransaction = this.savingsAccountHelper.getSavingsTransaction(savingsId, newWithdrawTransactionId);
    balance = balance + Float.parseFloat(WITHDRAW_AMOUNT) - Float.parseFloat(WITHDRAW_AMOUNT_ADJUSTED);
    assertEquals(Float.valueOf(WITHDRAW_AMOUNT_ADJUSTED), newWithdrawTransaction.get("amount"), "Verifying adjusted Amount");
    assertEquals(balance, newWithdrawTransaction.get("runningBalance"), "Verifying Balance after adjust");
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("accountBalance"), "Verifying Adjusted Balance");
    withdrawTransaction = this.savingsAccountHelper.getSavingsTransaction(savingsId, withdrawTransactionId);
    Assertions.assertTrue((Boolean) withdrawTransaction.get("reversed"));
    this.savingsAccountHelper.undoSavingsAccountTransaction(savingsId, newWithdrawTransactionId);
    newWithdrawTransaction = this.savingsAccountHelper.getSavingsTransaction(savingsId, withdrawTransactionId);
    Assertions.assertTrue((Boolean) newWithdrawTransaction.get("reversed"));
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    balance += Float.parseFloat(WITHDRAW_AMOUNT_ADJUSTED);
    assertEquals(balance, summary.get("accountBalance"), "Verifying Balance After Undo Transaction");
    error = (List) savingsAccountHelperValidationError.withdrawalFromSavingsAccount(savingsId, "5000", SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.insufficient.account.balance", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    error = (List) savingsAccountHelperValidationError.withdrawalFromSavingsAccount(savingsId, "5000", SavingsAccountHelper.getFutureDate(), CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.in.the.future", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    error = (List) savingsAccountHelperValidationError.depositToSavingsAccount(savingsId, "5000", SavingsAccountHelper.getFutureDate(), CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.in.the.future", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    error = (List) savingsAccountHelperValidationError.withdrawalFromSavingsAccount(savingsId, "5000", SavingsAccountHelper.CREATED_DATE_MINUS_ONE, CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.before.activation.date", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
    error = (List) savingsAccountHelperValidationError.depositToSavingsAccount(savingsId, "5000", SavingsAccountHelper.CREATED_DATE_MINUS_ONE, CommonConstants.RESPONSE_ERROR);
    assertEquals("error.msg.savingsaccount.transaction.before.activation.date", error.get(0).get(CommonConstants.RESPONSE_ERROR_MESSAGE_CODE));
}

